CREATE TABLE public.dim_date (
  sk_date DATE NOT NULL,
  year INTEGER,
  month INTEGER,
  month_name VARCHAR(15),
  day INTEGER,
  day_of_year INTEGER,
  week_day INTEGER,
  weekday_name VARCHAR(15),
  calendar_week INTEGER,
  brz_date CHAR(10),
  usa_date CHAR(10),
  universal_date CHAR(10),
  quarter VARCHAR(2),
  year_quarter VARCHAR(10),
  year_month VARCHAR(10),
  year_calendar_week VARCHAR(10),
  weekend VARCHAR(10),
  is_brz_holiday VARCHAR(10),
  brz_season VARCHAR(10),
  week_start DATE,
  week_end DATE,
  month_start DATE,
  month_end DATE,
  last_day DATE,
  last_week DATE,
  last_2_weeks DATE,
  last_4_weeks DATE,
  last_month DATE,
  last_quarter DATE,
  last_year DATE,
  CONSTRAINT dim_date_pkey PRIMARY KEY(sk_date)
) ;

